type Product = {
  id: number;
  name: string;
  category: string;
  price_minor: number;
  stock: number;
};

function isIntegerAtLeast(value: unknown, minimum: number): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= minimum;
}

function isNonEmptyText(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

function isProduct(value: unknown): value is Product {
  return typeof value === 'object' && value !== null
    && 'id' in value && isIntegerAtLeast(value.id, 1)
    && 'name' in value && isNonEmptyText(value.name)
    && 'category' in value && isNonEmptyText(value.category)
    && 'price_minor' in value && isIntegerAtLeast(value.price_minor, 0)
    && 'stock' in value && isIntegerAtLeast(value.stock, 0);
}

function decodeProducts(payload: unknown): Product[] {
  if (!Array.isArray(payload) || !payload.every(isProduct)) {
    throw new Error('استجابة الكتالوج تخالف عقد البيانات');
  }
  return payload;
}

async function readProducts(response: Response): Promise<Product[]> {
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const payload: unknown = await response.json();
  return decodeProducts(payload);
}

